import java.util.HashSet;

class Student {
    String name;
    public Student(String name) { this.name = name; }

    // What if we remove these methods?
    public int hashCode() { return name.hashCode(); }
    public boolean equals(Object o) {
        return ((Student)o).name.equals(this.name);
    }
}

public class Main {
    public static void main(String[] args) {
        HashSet<Student> set = new HashSet<>();

        set.add(new Student("Jammy"));
        set.add(new Student("Jammy")); // Duplicate?

        // If hashCode/equals are missing -> size is 2 (Wrong)
        // If present -> size is 1 (Correct)
        System.out.println("Size: " + set.size());
    }
}
